// Executavel unico: leva a pasta do app comprimida dentro de si, extrai uma vez para
// %LOCALAPPDATA%\mdb2sql\zig-imgui-<versao>-<hash>\ e roda o mdb2sql-zig.exe de la com os mesmos argumentos.
// Versoes velhas desse cache (outras pastas zig-imgui-*) sao apagadas.
// !T: Single-file launcher: payload (gzip, generated by build.zig) -> per-version cache -> run the app

const std = @import("std");
const payload = @import("payload"); // gerado pelo build.zig: version + files (nome, gzip)
const Io = std.Io;
const flate = std.compress.flate;

extern "user32" fn MessageBoxW(hwnd: ?*anyopaque, text: [*:0]const u16, caption: [*:0]const u16, kind: c_uint) callconv(.winapi) c_int;

const prefix = "zig-imgui-";

fn fail(comptime fmt: []const u8, args: anytype) noreturn {
    var buf: [1024]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, fmt, args) catch fmt;
    var wide: [1024:0]u16 = undefined;
    const n = std.unicode.wtf8ToWtf16Le(&wide, msg) catch 0;
    wide[n] = 0;
    _ = MessageBoxW(null, &wide, std.unicode.utf8ToUtf16LeStringLiteral("MDB2SQL (Zig + Dear ImGui)"), 0x10); // MB_ICONERROR
    std.process.exit(1);
}

pub fn main(init: std.process.Init) void {
    run(init) catch |e| fail("Could not start MDB2SQL: {t}", .{e});
}

fn run(init: std.process.Init) !void {
    const io = init.io;
    const arena = init.arena.allocator();
    const local = init.environ_map.get("LOCALAPPDATA") orelse return error.NoLocalAppData;
    const root = try std.fs.path.join(arena, &.{ local, "mdb2sql" });

    // pasta pelo conteudo: um build novo com a mesma versao nao reaproveita arquivos velhos
    var h: std.hash.Wyhash = .init(0);
    for (payload.files) |f| {
        h.update(f.name);
        h.update(f.data);
    }
    const name = try std.fmt.allocPrint(arena, prefix ++ "{s}-{x:0>16}", .{ payload.version, h.final() });
    const dir = try std.fs.path.join(arena, &.{ root, name });
    const exe = try std.fs.path.join(arena, &.{ dir, "mdb2sql-zig.exe" });
    const marker = try std.fs.path.join(arena, &.{ dir, ".complete" });

    const cwd = Io.Dir.cwd();
    if (cwd.access(io, marker, .{})) |_| {} else |_| {
        try cwd.createDirPath(io, root);
        // extrai numa pasta temporaria e so depois renomeia: dois inicios ao mesmo tempo nao se atrapalham
        const tmp = try std.fmt.allocPrint(arena, "{s}.tmp-{x}", .{ dir, randomU64(io) });
        errdefer cwd.deleteTree(io, tmp) catch {};
        try extract(io, tmp);
        cwd.rename(tmp, cwd, dir, io) catch {
            cwd.deleteTree(io, tmp) catch {};
            cwd.access(io, marker, .{}) catch |e| return e; // outro inicio ja extraiu: segue com o dele
        };
    }
    cleanOld(io, root, name);

    // mesmos argumentos; argv[0] passa a ser o exe extraido
    const args = try init.minimal.args.toSlice(arena);
    const argv = try arena.alloc([]const u8, @max(args.len, 1));
    argv[0] = exe;
    for (args[1..], 1..) |a, i| argv[i] = a;
    var child = try std.process.spawn(io, .{ .argv = argv });
    const term = try child.wait(io);
    std.process.exit(switch (term) {
        .exited => |code| code,
        else => 1,
    });
}

fn extract(io: Io, dir: []const u8) !void {
    const cwd = Io.Dir.cwd();
    try cwd.createDirPath(io, dir);
    var window: [flate.max_window_len]u8 = undefined;
    var path_buf: [4096]u8 = undefined;
    for (payload.files) |f| {
        const path = try std.fmt.bufPrint(&path_buf, "{s}\\{s}", .{ dir, f.name });
        if (std.fs.path.dirname(path)) |sub| try cwd.createDirPath(io, sub);
        const file = try cwd.createFile(io, path, .{});
        defer file.close(io);
        var wbuf: [64 * 1024]u8 = undefined;
        var w = file.writer(io, &wbuf);
        var src: Io.Reader = .fixed(f.data);
        var d: flate.Decompress = .init(&src, .gzip, &window);
        _ = try d.reader.streamRemaining(&w.interface);
        try w.end();
    }
    const marker = try std.fmt.bufPrint(&path_buf, "{s}\\.complete", .{dir});
    (try cwd.createFile(io, marker, .{})).close(io);
}

// Apaga as outras versoes deste app no cache (as em uso por outra janela aberta ficam: o erro e ignorado)
fn cleanOld(io: Io, root: []const u8, keep: []const u8) void {
    var dir = Io.Dir.cwd().openDir(io, root, .{ .iterate = true }) catch return;
    defer dir.close(io);
    var names: [32][128]u8 = undefined;
    var lens: [32]usize = undefined;
    var n: usize = 0;
    var it = dir.iterate();
    while (it.next(io) catch null) |entry| {
        if (entry.kind != .directory or !std.mem.startsWith(u8, entry.name, prefix)) continue;
        // a pasta atual e as extracoes dela ainda em andamento (keep.tmp-*) ficam
        if (std.mem.startsWith(u8, entry.name, keep) or entry.name.len > 128 or n == names.len) continue;
        @memcpy(names[n][0..entry.name.len], entry.name);
        lens[n] = entry.name.len;
        n += 1;
    }
    for (names[0..n], lens[0..n]) |*nm, len| dir.deleteTree(io, nm[0..len]) catch {};
}

fn randomU64(io: Io) u64 {
    var b: [8]u8 = undefined;
    io.random(&b);
    return std.mem.readInt(u64, &b, .little);
}
